gdV(){return"\u10e1\u10dd\u10e4\u10e2\u10e3\u10d4\u10e0\u10d8"},
gcY(){return"\u10d0\u10e0 \u10d0\u10e0\u10e1\u10d4\u10d1\u10dd\u10d1\u10e1 \u10d8\u10dc\u10e4\u10dd\u10e0\u10db\u10d0\u10ea\u10d8\u10d0 \u10d0\u10db \u10eb\u10d8\u10d4\u10d1\u10d0\u10e8\u10d8"},
gdG(){return"\u10d3\u10d0\u10da\u10d0\u10d2\u10d4\u10d1\u10d0 \u10e1\u10d0\u10d7\u10d0\u10e3\u10e0\u10d8\u10d7"},
gdF(){return"\u10d3\u10d0\u10da\u10d0\u10d2\u10d4\u10d1\u10d0 \u10d0\u10e6\u10ec\u10d4\u10e0\u10d8\u10d7"},
geE(){return"\u10d3\u10d0\u10da\u10d0\u10d2\u10d4\u10d1\u10d0 \u10e1\u10d0\u10ee\u10d4\u10da\u10d8\u10d7"},
