gec(){return"\u10dc\u10d0\u10ee\u10d5\u10d0"},
gca(a){return"\u10d3\u10d0\u10ee\u10e3\u10e0\u10d5\u10d0"},
geK(a){return"\u10d5\u10d4\u10e0\u10e1\u10d8\u10d0"},
gem(a){return"\u10d2\u10d0\u10d3\u10db\u10dd\u10ec\u10d4\u10e0\u10d0"},
geo(){return"\u10d4\u10e1 \u10d4\u10da\u10d4\u10e5\u10e2\u10e0\u10dd\u10dc\u10e3\u10da\u10d8 \u10e4\u10dd\u10e1\u10e2\u10d0 \u10d0\u10e0 \u10d0\u10e0\u10d8\u10e1 \u10d5\u10d0\u10da\u10d8\u10d3\u10e3\u10e0\u10d8"},
